'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const money=n=>'J$'+Number(n).toLocaleString('en-JM');
$('.menu-toggle')?.addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open)});
const chat=$('#whatsapp-form');
if(chat){const item=new URLSearchParams(location.search).get('product');if(item){chat.elements.topic.value='Product Gallery';chat.elements.message.value='I’d like to order or ask about: '+item;}const topic=new URLSearchParams(location.search).get('topic');if(topic&&[...chat.elements.topic.options].some(o=>o.value===topic))chat.elements.topic.value=topic;chat.addEventListener('submit',e=>{e.preventDefault();if(!chat.elements.name.value.trim()){chat.elements.name.setCustomValidity('Please enter your name.');chat.elements.name.reportValidity();return;}const d=new FormData(chat);location.href='https://wa.me/18768124295?text='+encodeURIComponent(`Hi ZenDoodle Studios! My name is ${d.get('name').trim()}.\n\nI’d like to chat about: ${d.get('topic')}.\n\n${d.get('message').trim()}`)});chat.elements.name.addEventListener('input',()=>chat.elements.name.setCustomValidity(''));}
const form=$('#order-form');
if(form){
 const products=window.ZEN_PRODUCTS, prices=window.ZEN_PRICING;let step=0,total=0;
 const field=n=>form.elements.namedItem(n),val=n=>field(n)?.value||'';
 const product=()=>products.find(p=>p.id===val('product'));
 const setOptions=(el,arr)=>{el.replaceChildren(...arr.map(([label,value])=>new Option(label,value)));};
 function showGroup(selector,on){$$(selector).forEach(el=>{el.hidden=!on;$$('input,select',el).forEach(i=>i.disabled=!on);});}
 function configure(){const p=product(),mini=p.id.startsWith('mini');$('#product-detail').textContent=p.detail;setOptions($('#package'),p.options.map(([label,price])=>[price?`${label} — ${money(price)}`:label,label]));setOptions($('#quantity'),(mini?[8,12,24,48]:p.id==='notepad'?[1,2,3]:[1,2,3,4,5]).map(n=>[String(n),String(n)]));showGroup('[data-mini]',mini);showGroup('[data-childmini]',p.id==='mini');showGroup('[data-activity]',p.id==='activity');showGroup('[data-notepad]',p.id==='notepad');showGroup('[data-series]',p.id==='series');showGroup('[data-custom-design]',p.id!=='series');calculate();}
 function deliveryOptions(){
 const area=val('parish');let options=[['Select an area first','']];
 if(['Kingston (KSMA)','St. Andrew (KSMA)'].includes(area))options=[['Kingston & St. Andrew — Free (KSMA Only) · J$0','KSMA — Free']];
 else if(area==='St. Catherine — Portmore')options=[['Portmore delivery · J$600','Portmore — J$600']];
 else if(area==='St. Catherine — Spanish Town (Square)')options=[['Spanish Town (Square) · J$600','Spanish Town Square — J$600']];
 else if(area)options=[['ZipMail — Post-to-Post · J$500','ZipMail — Post-to-Post'],['Knutsford Express — up to 10 lbs · J$700','Knutsford Express — up to 10 lbs'],['Tara Couriers — Door to Door · Starting at J$2,150','Tara Couriers — Starting at J$2,150']];
 setOptions(field('delivery'),options);
 }
 function deliveryCost(){return {'KSMA — Free':0,'Portmore — J$600':600,'Spanish Town Square — J$600':600,'ZipMail — Post-to-Post':500,'Knutsford Express — up to 10 lbs':700,'Tara Couriers — Starting at J$2,150':2150}[val('delivery')]||0;}
 function calculate(){const p=product(),qty=Number(val('quantity')),mini=p.id.startsWith('mini');let base=p.options.find(o=>o[0]===val('package'))?.[1]||0,lines=[];if(mini){const index=[8,12,24,48].indexOf(qty),kind=$('#package').selectedIndex;base=prices.mini[p.id][kind][index];lines.push([`${qty}-book pack`,base]);if(val('size')==='large')lines.push(['Larger size',prices.large[index]]);if(field('pencils').checked)lines.push(['Crayons / pencils',prices.pencils[index]]);}else{base*=qty;if(p.id==='notepad'&&qty===3)base*=.95;lines.push([`${qty} × ${p.name}`,base]);if(p.id==='activity'&&field('gift').checked)lines.push(['Gift packaging',prices.gift*qty]);}if(val('turnaround')==='rush')lines.push(['Rush service',prices.rush]);for(const [name,label,price] of [['extra_crayons','4-Pack Crayons',150],['extra_pencils','12-Pack Coloured Pencils',600],['extra_markers','8-Pack Dot Markers',650]]){const n=Number(val(name));if(Number.isInteger(n)&&n>0&&n<=100)lines.push([`${n} × ${label}`,n*price]);}if(val('delivery'))lines.push([val('delivery'),deliveryCost()]);$('#delivery-estimate').value=deliveryCost();total=lines.reduce((s,l)=>s+l[1],0);$('#summary-product').textContent=p.name;$('#total').textContent=money(total);$('#estimate-field').value=total;$('#price-lines').replaceChildren(...lines.map(([a,b])=>{const row=document.createElement('p'),label=document.createElement('span'),amount=document.createElement('strong');label.textContent=a;amount.textContent=money(b);row.append(label,amount);return row;}));}
 function validate(n){const fs=$(`[data-step="${n}"]`);for(const el of $$('input,select,textarea',fs)){if(el.disabled)continue;if(el.type==='text'&&el.required)el.setCustomValidity(el.value.trim()?'':'Please complete this field.');if(!el.checkValidity()){el.reportValidity();return false;}}if(n===0&&product().id==='notepad'){const count=$$('input[name=layouts]:checked').length;if(count<1||count>2){$('#form-error').textContent='Please choose one or two notepad layouts.';return false;}}return true;}
 const labels={product:'Product',package:'Package',quantity:'Quantity',size:'Size',mini_type:'Mini book type',pencils:'Crayons / pencils',gift:'Gift packaging',layouts:'Notepad layouts',extra_crayons:'4-Pack Crayons (packs)',extra_pencils:'12-Pack Coloured Pencils (packs)',extra_markers:'8-Pack Dot Markers (packs)',recipient:'Recipient / event',age:'Age',theme:'Theme',colours:'Colours',occasion:'Occasion',photo_1:'Reference photo 1',photo_2:'Reference photo 2',notes:'Special requests',name:'Your name',email:'Email',phone:'Phone / WhatsApp',parish:'Parish',delivery:'Delivery',needed_by:'Needed by',turnaround:'Turnaround'};
 function review(){const dl=document.createElement('dl'),data=new FormData(form);for(const [key,label]of Object.entries(labels)){let values=data.getAll(key).map(v=>v instanceof File?v.name:v).filter(Boolean);if(!values.length)continue;let value=values.join(', ');if(key==='product')value=product().name;if(key==='turnaround')value=value==='rush'?'Rush — subject to availability':'Standard — 7 business days';const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent='Estimated total (includes selected delivery estimate)';dd.textContent=money(total);dl.append(dt,dd);$('#review').replaceChildren(dl);}
 function render(focus=true){$$('[data-step]').forEach((el,i)=>el.hidden=i!==step);$$('.steps li').forEach((el,i)=>{el.classList.toggle('active',i<=step);if(i===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});$('#back').hidden=step===0;$('#next').hidden=step===3;$('#submit').hidden=step!==3;$('#form-error').textContent='';if(step===3)review();if(focus){const legend=$(`[data-step="${step}"] legend`);legend.tabIndex=-1;legend.focus();}}
 $('#next').addEventListener('click',()=>{if(validate(step)){step++;render();}});$('#back').addEventListener('click',()=>{step--;render();});
 form.addEventListener('input',e=>{if(e.target.type==='text')e.target.setCustomValidity('');calculate();});
 form.addEventListener('change',e=>{if(e.target.id==='product')configure();else {if(e.target.name==='parish')deliveryOptions();calculate();}if(e.target.type==='file'){const file=e.target.files[0];e.target.setCustomValidity(file&&(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024)?'Choose a JPG, PNG or WebP photo no larger than 3 MB.':'');e.target.reportValidity();}});
 form.noValidate=true;
 form.addEventListener('submit',async e=>{e.preventDefault();if(step!==3){if(validate(step)){step++;render();}return;}for(let n=0;n<4;n++){step=n;render(false);if(!validate(n))return;}step=3;render(false);if(form.dataset.preview==='true'){$('#form-error').textContent='Preview complete! Your order has not been sent. On the live website, this step sends your request to ZenDoodle Studios.';return;}if(location.protocol==='file:'||['localhost','127.0.0.1','terminal.local'].includes(location.hostname)||location.hostname.endsWith('.github.io')){$('#form-error').textContent='Email ordering is available on our Netlify-hosted website. Please use WhatsApp to contact us while viewing this copy.';return;}const btn=$('#submit');btn.disabled=true;btn.textContent='Sending your request…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form)});if(!response.ok)throw Error('submission');location.href='thank-you.html';}catch{ $('#form-error').textContent='Your request could not be sent. Your details are still here—please try again, or contact us on WhatsApp.';btn.disabled=false;btn.textContent='Send order request';}});
 const requested=new URLSearchParams(location.search).get('product');if(products.some(p=>p.id===requested))field('product').value=requested;
 const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());field('needed_by').min=date.toISOString().slice(0,10);
 deliveryOptions();configure();const params=new URLSearchParams(location.search);const requestedAge=params.get('age');if(product().id==='series'&&product().options.some(o=>o[0]===requestedAge))field('package').value=requestedAge;const addon=params.get('addon');if(['crayons','pencils','markers'].includes(addon))field('extra_'+addon).value=1;calculate();render(false);
 if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  try{Promise.resolve(document.modelContext.registerTool({name:'read_order_estimate',title:'Read order estimate',description:'Read the current product selection and estimated JMD total. Does not submit an order.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');return {product:product().name,package:val('package'),quantity:Number(val('quantity')),estimatedTotalJMD:total,deliveryIncluded:!!val('delivery'),deliveryEstimateJMD:deliveryCost()};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 }
}
